package com.bananalab.lite;
import android.content.*;import org.json.*;import java.io.*;import java.util.*;import java.util.regex.*;import java.lang.reflect.*;
/** New user-defined pure function, outside the old constant-setting catalogue. */
final class JavaFunction{
 static volatile Method active;static int loaded=-1;
 static SharedPreferences prefs(Context c){return c.getSharedPreferences("banana-java-function",0);}
 static Method method(Context c,String jar)throws Exception{return OnDeviceJava.load(c,new File(jar)).getClassLoader().loadClass("com.bananalab.patch.BananaFunction").getMethod("jump",float.class);}
 static void verify(Method method,JavaCurve curve)throws Exception{for(int i=0;i<=256;i++){float t=i/256f,v=((Number)method.invoke(null,t)).floatValue();if(Float.isNaN(v)||Float.isInfinite(v)||Math.abs(v-curve.value(t))>.001)throw new IOException("La función no pasó la comprobación.");}}
 static synchronized void restore(Context c){int revision=prefs(c).getInt("revision",0);if(loaded==revision)return;try{String raw=prefs(c).getString("active","");Method m=null;if(!raw.isEmpty()){JSONObject j=new JSONObject(raw);JavaCurve curve=new JavaCurve(j.getString("expression"));if(!curve.source().equals(j.getString("source")))throw new IOException("Fuente modificada");m=method(c,j.getString("jar"));verify(m,curve);}active=m;loaded=revision;}catch(Throwable e){active=null;loaded=revision;prefs(c).edit().putString("error","No cargué la función; usé el salto anterior: "+e.getClass().getSimpleName()).apply();}}
 static float lift(float t,float previous){Method m=active;if(m==null)return previous;try{float x=((Number)m.invoke(null,Math.max(0,Math.min(1,t)))).floatValue();return Float.isNaN(x)||Float.isInfinite(x)?previous:Math.max(-40,Math.min(0,x));}catch(Exception e){return previous;}}
 static synchronized String prepare(Context c,String expression)throws Exception{JavaCurve curve=new JavaCurve(expression);int base=prefs(c).getInt("revision",0);String prior=prefs(c).getString("active","");Map<String,String> files=new LinkedHashMap<>();files.put("BananaBehavior.java",JavaPatchPolicy.BASE);files.put("BananaFunction.java",curve.source());JavaChat.phase("Compilando la nueva función Java del salto…");OnDeviceJava.Build built=OnDeviceJava.compileSources(c,files);JavaChat.phase("Probando la función en otro proceso…");android.os.Bundle trial=JavaTrial.run(c,built.jar,expression);if(prefs(c).getInt("revision",0)!=base||!prefs(c).getString("active","").equals(prior))throw new IOException("La versión cambió durante la prueba.");JSONObject draft=new JSONObject().put("expression",expression).put("source",curve.source()).put("jar",built.jar.getAbsolutePath()).put("base",base).put("prior",prior).put("trialPid",trial.getInt("pid")).put("samples",trial.getInt("samples"));if(!prefs(c).edit().putString("draft",draft.toString()).commit())throw new IOException("No pude guardar la función probada.");return "Preparé una función Java nueva para la curva del salto. Compiló y coincidió con la fórmula en257 puntos, en otro proceso.\nTodavía no está activa. Decí ‘aplica la funcion del salto’, ‘mostrame la prueba del salto’ o ‘descarta la funcion del salto’.";}
 static JSONArray history(Context c)throws Exception{return new JSONArray(prefs(c).getString("history","[]"));}
 static JSONArray archived(Context c)throws Exception{JSONArray all=history(c),next=new JSONArray();for(int i=Math.max(0,all.length()-7);i<all.length();i++)next.put(all.getJSONObject(i));next.put(new JSONObject().put("revision",prefs(c).getInt("revision",0)).put("active",prefs(c).getString("active","")));return next;}
 static synchronized String apply(Context c)throws Exception{String raw=prefs(c).getString("draft","");if(raw.isEmpty())return "No hay una función del salto pendiente.";JSONObject d=new JSONObject(raw);int rev=prefs(c).getInt("revision",0);if(d.getInt("base")!=rev||!d.getString("prior").equals(prefs(c).getString("active","")))throw new IOException("La prueba está desactualizada. Prepará otra función.");JavaCurve curve=new JavaCurve(d.getString("expression"));if(!curve.source().equals(d.getString("source")))throw new IOException("La fuente cambió desde la prueba.");JavaTrial.run(c,new File(d.getString("jar")),d.getString("expression"));Method m=method(c,d.getString("jar"));verify(m,curve);if(!prefs(c).edit().putString("history",archived(c).toString()).putString("active",raw).putInt("revision",rev+1).putLong("changedAt",System.currentTimeMillis()).remove("draft").remove("error").commit())throw new IOException("No pude activar la función.");active=m;loaded=rev+1;return "Listo. La función Java nueva está activa en los saltos de la vista previa y la exportación. Podés pedir ‘deshace la funcion del salto’. Tus escenas se conservan.";}
 static synchronized String undo(Context c)throws Exception{JSONArray h=history(c);if(h.length()==0)return "No hay una función anterior para recuperar.";JSONObject last=h.getJSONObject(h.length()-1);String old=last.getString("active");Method m=null;if(!old.isEmpty()){JSONObject j=new JSONObject(old);JavaCurve curve=new JavaCurve(j.getString("expression"));if(!curve.source().equals(j.getString("source")))throw new IOException("La fuente guardada cambió.");JavaTrial.run(c,new File(j.getString("jar")),j.getString("expression"));m=method(c,j.getString("jar"));verify(m,curve);}JSONArray next=archived(c);int rev=prefs(c).getInt("revision",0);if(!prefs(c).edit().putString("history",next.toString()).putString("active",old).putInt("revision",rev+1).putLong("changedAt",System.currentTimeMillis()).remove("draft").remove("error").commit())throw new IOException("No pude recuperar la función.");active=m;loaded=rev+1;return "Recuperé la función anterior del salto. Las escenas y los personajes se conservan.";}
 static String preview(Context c)throws Exception{String raw=prefs(c).getString("draft",prefs(c).getString("active",""));if(raw.isEmpty())return "No hay una función nueva del salto para mostrar.";JavaCurve curve=new JavaCurve(new JSONObject(raw).getString("expression"));StringBuilder out=new StringBuilder("Prueba de la curva del salto (sin modificar la escena):");for(float t:new float[]{0,.25f,.5f,.75f,1})out.append("\n").append(Math.round(t*100)).append("% → altura ").append(-curve.value(t));return out.append("\nLa altura final también usa el multiplicador global de saltos de la app.").toString();}
 static BananaEngine.Result handle(Context c,String input)throws Exception{String q=ChatLanguage.normalize(input),expression=null;
  if(q.equals("como cambio la funcion del salto"))return MobileCore.say(c,"Podés crear una función nueva por chat:\n• Hace que el salto suba rapido y baje lento.\n• Cambia la forma del salto: altura 18, subida 30, pausa hasta 60.\nLos porcentajes son posiciones dentro del salto. Después: ‘aplica la funcion del salto’.\nPara una fórmula propia: ‘reescribe la funcion del salto: -100*t*(1-t)’. Admite t, operaciones, sin/cos/abs/min/max y condiciones t < número ? expresión : expresión. No acepta instrucciones Java generales.\nLa prueba ocurre en un proceso privado separado que comparte los permisos de la app; no es un sandbox para código arbitrario.","app_ajuste");
  if(q.startsWith("reescribe la funcion del salto")||q.startsWith("prepara una funcion de salto")){int colon=input.indexOf(':');if(colon<0)return MobileCore.say(c,"Poné la fórmula después de dos puntos. Ejemplo: ‘reescribe la funcion del salto: -100*t*(1-t)’.","app_ajuste");String prefix=ChatLanguage.normalize(input.substring(0,colon));if(!prefix.matches("reescribe la funcion del salto|prepara una funcion de salto"))return MobileCore.say(c,"No entendí el pedido completo. No cambié nada; separá la fórmula de otros pedidos.","app_ajuste");expression=input.substring(colon+1).trim();if(expression.startsWith("return "))expression=expression.substring(7).trim();if(expression.endsWith(";"))expression=expression.substring(0,expression.length()-1).trim();}
  Matcher natural=Pattern.compile("cambia la forma del salto altura ([0-9]{1,3}) subida ([0-9]{1,3}) pausa hasta ([0-9]{1,3})").matcher(q);if(natural.matches())try{expression=JavaCurve.natural(Integer.parseInt(natural.group(1)),Integer.parseInt(natural.group(2)),Integer.parseInt(natural.group(3)));}catch(IllegalArgumentException e){return MobileCore.say(c,e.getMessage(),"app_ajuste");}
  if(q.equals("hace que el salto suba rapido y baje lento"))expression=JavaCurve.natural(12,25,25);
  if(q.equals("hace que el salto suba lento y baje rapido"))expression=JavaCurve.natural(12,75,75);
  if(q.equals("mostrame la prueba del salto"))return MobileCore.say(c,preview(c),"app_ajuste");
  if(q.equals("mostrame la funcion del salto")){String raw=prefs(c).getString("draft",prefs(c).getString("active",""));return MobileCore.say(c,raw.isEmpty()?"El salto usa el motor anterior; no hay una función nueva.":(prefs(c).contains("draft")?"Borrador probado, sin activar:\n":"Función activa:\n")+new JSONObject(raw).getString("source"),"app_ajuste");}
  if(q.equals("descarta la funcion del salto")){if(!prefs(c).edit().remove("draft").commit())throw new IOException("No pude descartar la prueba.");return MobileCore.say(c,"Descarté el candidato. La función activa se conserva.","app_ajuste");}
  boolean generic=q.matches("deshace ese ajuste|deshace el ultimo ajuste de la app|volve al funcionamiento anterior")&&prefs(c).getLong("changedAt",0)>Math.max(JavaLive.prefs(c).getLong("changedAt",0),AppJavaWorkspace.prefs(c).getLong("changedAt",0));
  if(expression==null&&!q.equals("aplica la funcion del salto")&&!q.equals("deshace la funcion del salto")&&!generic){if(q.startsWith("cambia la forma del salto"))return MobileCore.say(c,"No entendí la curva completa. Pedí ‘como cambio la funcion del salto’ para ver ejemplos. No cambié nada.","app_ajuste");return null;}
  JavaChat.owner=Thread.currentThread();try{String result=expression!=null?prepare(c,expression):q.equals("aplica la funcion del salto")?apply(c):undo(c);return MobileCore.say(c,result,"app_ajuste");}catch(Throwable e){prefs(c).edit().putString("error",e.getClass().getSimpleName()+": "+e.getMessage()).apply();return MobileCore.say(c,"No activé una función nueva; conservé la anterior.\n"+e.getMessage(),"app_ajuste");}finally{JavaChat.owner=null;JavaChat.progress="";}
 }
}
